//! In-process metadata-only provider/recorder boundary controls. No daemon,
//! game world, parser reconstruction, pins or full-workspace test subprocess.
#[path="../../../shared/test_scratch.rs"]mod test_scratch;
use dmbc::input_snapshot::{RecordingInputs,SnapshotProvider,Stamp,FolderListing,FileSystemInputs,InputSnapshot};
use dm_preprocess::{SourceProvider,source_arena_credit::{SourceArenaWork,SourceArenaCredit,SourceArenaCreditOwner}};
use std::{any::Any,io,path::{Path,PathBuf},sync::{Arc,atomic::{AtomicBool,AtomicUsize,Ordering}}};
#[derive(Default)]struct State{present:AtomicBool,fail:AtomicBool,probes:AtomicUsize}
#[derive(Clone)]struct Metadata(Arc<State>);
impl SnapshotProvider for Metadata{
 fn path_presence(&self,_:&Path)->io::Result<bool>{self.0.probes.fetch_add(1,Ordering::AcqRel);if self.0.fail.load(Ordering::Acquire){Err(io::Error::from_raw_os_error(1450))}else{Ok(self.0.present.load(Ordering::Acquire))}}
 fn stamp(&self,_:&Path)->io::Result<Stamp>{panic!("presence must not pretend to be a content-bearing stamp")}
 fn read(&self,_:&Path)->io::Result<(Stamp,Vec<u8>)>{panic!("metadata observation must never read payload bytes")}
 fn list(&self,_:&Path)->io::Result<FolderListing>{panic!("presence must not enumerate directory children")}
}
struct Credit{bytes:AtomicUsize,live:Arc<AtomicUsize>}
impl Drop for Credit{fn drop(&mut self){self.live.fetch_sub(self.bytes.load(Ordering::Acquire),Ordering::AcqRel);}}
impl SourceArenaCreditOwner for Credit{fn as_any(&self)->&dyn Any{self}fn reserved_bytes(&self)->usize{self.bytes.load(Ordering::Acquire)}fn visit_storage(&self,_:&mut dyn FnMut(usize,usize)){}}
struct Work{live:Arc<AtomicUsize>,limit:usize}
impl Work{fn new(limit:usize)->Self{Self{live:Arc::new(AtomicUsize::new(0)),limit}}fn charge(&self,n:usize)->io::Result<()>{self.live.fetch_update(Ordering::AcqRel,Ordering::Acquire,|old|old.checked_add(n).filter(|total|*total<=self.limit)).map(|_|()).map_err(|_|io::ErrorKind::OutOfMemory.into())}fn own<'a>(&self,c:&'a SourceArenaCredit)->io::Result<&'a Credit>{let owner=c.owner().as_any().downcast_ref::<Credit>().ok_or(io::ErrorKind::InvalidInput)?;if !Arc::ptr_eq(&owner.live,&self.live){return Err(io::ErrorKind::InvalidInput.into())}Ok(owner)}}
impl SourceArenaWork for Work{
 fn checkpoint(&self)->io::Result<()>{Ok(())}
 fn reserve(&self,n:usize)->io::Result<SourceArenaCredit>{self.charge(n)?;Ok(SourceArenaCredit::from_resource_owner(Arc::new(Credit{bytes:AtomicUsize::new(n),live:self.live.clone()})))}
 fn grow(&self,c:&mut SourceArenaCredit,n:usize)->io::Result<()>{let owner=self.own(c)?;self.charge(n)?;owner.bytes.fetch_add(n,Ordering::AcqRel);Ok(())}
 fn shrink(&self,c:&mut SourceArenaCredit,n:usize)->io::Result<()>{let owner=self.own(c)?;owner.bytes.fetch_update(Ordering::AcqRel,Ordering::Acquire,|old|old.checked_sub(n)).map_err(|_|io::ErrorKind::InvalidInput)?;self.live.fetch_sub(n,Ordering::AcqRel);Ok(())}
}
fn path(name:&str)->PathBuf{PathBuf::from("E:/dq-cache/test-scratch").join(name)}
#[test]fn positive_and_negative_follow_target_revalidation_never_read_payloads_or_folders(){
 let state=Arc::new(State::default());state.present.store(true,Ordering::Release);let provider=Metadata(state.clone());let work=Work::new(4<<20);let input=RecordingInputs::new(provider.clone(),0);let target=path("metadata-only.dmm");assert!(SourceProvider::path_presence_admitted(&input,&target,&work).unwrap());let snapshot=input.snapshot().unwrap();assert!(snapshot.files().next().is_none());let(report,_)=snapshot.validate(&provider,false,1).unwrap();assert!(report.unchanged());assert_eq!(report.rehashed,0);state.present.store(false,Ordering::Release);let(report,refreshed)=snapshot.validate(&provider,false,2).unwrap();assert_eq!(report.changed,[target.clone()]);assert_eq!(report.rehashed,0);assert!(!snapshot.restat(&provider).unwrap().unchanged());let json=serde_json::to_value(&refreshed).unwrap();assert_eq!(json["path_presence"][target.to_string_lossy().as_ref()],false);drop((refreshed,snapshot,input));assert_eq!(work.live.load(Ordering::Acquire),0);
}
#[test]fn absent_then_present_is_a_changed_fact_not_a_stale_negative_or_source_acquisition(){
 let state=Arc::new(State::default());let provider=Metadata(state.clone());let work=Work::new(4<<20);let input=RecordingInputs::new(provider.clone(),0);let target=path("metadata-missing.dmf");assert!(!SourceProvider::path_presence_admitted(&input,&target,&work).unwrap());let snapshot=input.snapshot().unwrap();state.present.store(true,Ordering::Release);let(report,_) =snapshot.validate(&provider,false,1).unwrap();assert_eq!(report.changed,[target.clone()]);assert!(SourceProvider::path_presence_admitted(&input,&target,&work).is_err(),"one capture cannot silently change its observed fact");assert!(snapshot.files().next().is_none());drop((snapshot,input));assert_eq!(work.live.load(Ordering::Acquire),0);
}
#[test]fn quota_is_rejected_before_metadata_io_and_first_actual_io_cannot_become_missing(){
 let state=Arc::new(State::default());let provider=Metadata(state.clone());let input=RecordingInputs::new(provider.clone(),0);let target=path("metadata-quota.dms");let tiny=Work::new(1);assert_eq!(SourceProvider::path_presence_admitted(&input,&target,&tiny).unwrap_err().kind(),io::ErrorKind::OutOfMemory);assert_eq!(state.probes.load(Ordering::Acquire),0);assert_eq!(tiny.live.load(Ordering::Acquire),0);let work=Work::new(4<<20);state.fail.store(true,Ordering::Release);assert_eq!(SourceProvider::path_presence_admitted(&input,&target,&work).unwrap_err().raw_os_error(),Some(1450));assert_eq!(work.live.load(Ordering::Acquire),0);let json=serde_json::to_value(input.snapshot().unwrap()).unwrap();assert!(json.get("path_presence").is_none());state.fail.store(false,Ordering::Release);state.present.store(true,Ordering::Release);let fresh=RecordingInputs::new(provider,0);assert!(SourceProvider::path_presence_admitted(&fresh,&target,&work).unwrap());drop((fresh,input));assert_eq!(work.live.load(Ordering::Acquire),0);
}
#[test]fn actual_metadata_directory_presence_and_exact_noncanonical_lookup_semantics_are_preserved(){
 let root=test_scratch::dir("unified-path-presence-exact");std::fs::create_dir_all(&root).unwrap();let file=root.join("file");std::fs::write(&file,b"not a directory").unwrap();let existing=root.join("existing");std::fs::write(&existing,b"").unwrap();let dir=root.join("directory");std::fs::create_dir_all(&dir).unwrap();let work=Work::new(4<<20);let input=RecordingInputs::new(FileSystemInputs,0);assert!(SourceProvider::path_presence_admitted(&input,&dir,&work).unwrap());assert!(SourceProvider::path_presence_admitted(&input,&existing,&work).unwrap());let exact=file.join("../existing");let actual_os_result=std::fs::metadata(&exact).is_ok();assert_eq!(SourceProvider::path_presence_admitted(&input,&exact,&work).unwrap(),actual_os_result,"the OS, not a POSIX assumption or lexical normalization, decides lookup");assert!(!SourceProvider::path_presence_admitted(&input,&root.join("missing"),&work).unwrap());let snapshot=input.snapshot().unwrap();let encoded=serde_json::to_value(&snapshot).unwrap();assert!(encoded["path_presence"].get(exact.to_string_lossy().as_ref()).is_some(),"retain exact requested spelling even when the OS normalizes it");assert!(snapshot.files().next().is_none());assert!(snapshot.restat(&FileSystemInputs).unwrap().unchanged());drop((snapshot,input));assert_eq!(work.live.load(Ordering::Acquire),0);
}
#[test]fn captured_metadata_owner_survives_snapshot_aliases_and_binary_codec_has_its_own_field(){
 let state=Arc::new(State::default());state.present.store(true,Ordering::Release);let input=RecordingInputs::new(Metadata(state),0);let work=Work::new(4<<20);assert!(SourceProvider::path_presence_admitted(&input,&path("metadata-codec.dmm"),&work).unwrap());let snapshot=input.snapshot().unwrap();let alias=snapshot.clone();let wire=dm_wire::encode(0x5350_0003,&snapshot).unwrap();let restored:InputSnapshot=dm_wire::decode(0x5350_0003,&wire,dm_wire::MAX_BYTES).unwrap();assert_eq!(restored,snapshot);let json=serde_json::to_value(&snapshot).unwrap();assert!(json.get("path_presence").is_some());drop((restored,snapshot,input));assert!(work.live.load(Ordering::Acquire)>0);drop(alias);assert_eq!(work.live.load(Ordering::Acquire),0);
}
#[cfg(any(unix,windows))]
#[test]fn actual_symlink_target_disappearance_is_reprobed_even_when_link_parent_is_unchanged(){
 let root=test_scratch::dir("unified-path-presence-symlink");std::fs::create_dir_all(&root).unwrap();let target=root.join("target");let link=root.join("link");std::fs::write(&target,b"").unwrap();
 #[cfg(unix)]std::os::unix::fs::symlink(&target,&link).unwrap();
 #[cfg(windows)]std::os::windows::fs::symlink_file(&target,&link).unwrap();
 let work=Work::new(4<<20);let input=RecordingInputs::new(FileSystemInputs,0);assert!(SourceProvider::path_presence_admitted(&input,&link,&work).unwrap());let snapshot=input.snapshot().unwrap();std::fs::remove_file(&target).unwrap();let(report,_)=snapshot.validate(&FileSystemInputs,false,1).unwrap();assert!(report.changed.contains(&link));drop((snapshot,input));assert_eq!(work.live.load(Ordering::Acquire),0);
}

#[test]fn frozen_journal_records_funded_presence_and_replay_never_falls_back_to_changed_filesystem(){
 let root=test_scratch::dir("unified-path-presence-journal");let path=root.join("only-metadata.dmm");std::fs::write(&path,b"the provider must not read this").unwrap();let directory=root.join("journal");let work=Work::new(4<<20);let journal=dmbc::frozen_inputs::Inputs::record(&directory).unwrap();
 {let input=RecordingInputs::new(&journal,0);assert!(SourceProvider::path_presence_admitted(&input,&path,&work).unwrap());let snapshot=input.snapshot().unwrap();assert!(snapshot.files().next().is_none());assert!(work.live.load(Ordering::Acquire)>0);}
 assert!(work.live.load(Ordering::Acquire)>0,"journal retains its separately funded SAME observation after snapshot dies");journal.finish().unwrap();let text=std::fs::read_to_string(directory.join("index.json")).unwrap();let index:serde_json::Value=serde_json::from_str(&text).unwrap();assert_eq!(index["path_presence_v1"][path.to_string_lossy().as_ref()],true);assert_eq!(index["files"].as_object().unwrap().len(),0);assert_eq!(std::fs::read_dir(directory.join("payloads")).unwrap().count(),0);drop(journal);assert_eq!(work.live.load(Ordering::Acquire),0);
 std::fs::remove_file(&path).unwrap();let replay=dmbc::frozen_inputs::Inputs::replay(&directory).unwrap();assert!(SnapshotProvider::path_presence(&replay,&path).unwrap());assert!(SnapshotProvider::path_presence(&replay,&root.join("unrecorded")).is_err(),"no live metadata fallback for an unobserved journal path");
}
#[test]fn genuinely_disjoint_admitted_union_requires_and_retains_the_actual_resource_host(){
 let state=Arc::new(State::default());state.present.store(true,Ordering::Release);let provider=Metadata(state);let work=Work::new(4<<20);let left=RecordingInputs::new(provider.clone(),0);let right=RecordingInputs::new(provider,0);assert!(SourceProvider::path_presence_admitted(&left,&path("left.dmm"),&work).unwrap());assert!(SourceProvider::path_presence_admitted(&right,&path("right.dmm"),&work).unwrap());let mut combined=left.snapshot().unwrap();let other=right.snapshot().unwrap();assert_eq!(combined.merge(&other).unwrap_err().kind(),io::ErrorKind::NotConnected,"a generic merge cannot deep-copy two admitted owners without a lender");combined.merge_path_presence_using(&other,&work).unwrap();combined.merge(&other).unwrap();assert!(combined.restat(&Metadata({let state=Arc::new(State::default());state.present.store(true,Ordering::Release);state})).unwrap().unchanged());drop((combined,other,left,right));assert_eq!(work.live.load(Ordering::Acquire),0);
}

#[test]fn actual_filesystem_invalid_path_is_source_false_without_masking_provider_or_work_errors(){let root=test_scratch::dir("metadata-source-fault-boundary");let invalid=root.join("embedded\0leaf");assert!(std::fs::metadata(&invalid).is_err());assert!(!FileSystemInputs.path_presence(&invalid).unwrap(),"old Path::exists returns false for an actual malformed lookup");let work=Work::new(4<<20);let input=RecordingInputs::new(FileSystemInputs,0);assert!(!SourceProvider::path_presence_admitted(&input,&invalid,&work).unwrap());drop(input);assert_eq!(work.live.load(Ordering::Acquire),0);struct Operational{calls:AtomicUsize}impl SnapshotProvider for Operational{fn path_presence(&self,_:&Path)->io::Result<bool>{self.calls.fetch_add(1,Ordering::AcqRel);Err(io::ErrorKind::PermissionDenied.into())}fn stamp(&self,_:&Path)->io::Result<Stamp>{unreachable!()}fn read(&self,_:&Path)->io::Result<(Stamp,Vec<u8>)>{unreachable!()}fn list(&self,_:&Path)->io::Result<FolderListing>{unreachable!()}}let input=RecordingInputs::new(Operational{calls:AtomicUsize::new(0)},0);assert_eq!(SourceProvider::path_presence_admitted(&input,&path("provider-fault"),&work).unwrap_err().kind(),io::ErrorKind::PermissionDenied,"arbitrary provider errors have no actual FS-source provenance");drop(input);assert_eq!(work.live.load(Ordering::Acquire),0);struct Denied;impl SourceArenaWork for Denied{fn checkpoint(&self)->io::Result<()>{Ok(())}fn grow(&self,_:&mut SourceArenaCredit,_:usize)->io::Result<()>{panic!("initial metadata pregrant must refuse before growth")}fn shrink(&self,_:&mut SourceArenaCredit,_:usize)->io::Result<()>{panic!("no metadata credit exists after denied pregrant")}fn reserve(&self,_:usize)->io::Result<SourceArenaCredit>{Err(io::ErrorKind::PermissionDenied.into())}}let state=Arc::new(State::default());let input=RecordingInputs::new(Metadata(state.clone()),0);assert_eq!(SourceProvider::path_presence_admitted(&input,&path("work-fault"),&Denied).unwrap_err().kind(),io::ErrorKind::PermissionDenied);assert_eq!(state.probes.load(Ordering::Acquire),0,"resource refusal precedes actual metadata call");}
